import{_ as s,C as o,o as r,c as n,j as e,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse(`{"title":"Watch a running test","description":"Watch the page of a Playwright test while it runs on your machine, from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app: up to ten images a second, through its next tests and stops.","frontmatter":{"title":"Watch a running test","description":"Watch the page of a Playwright test while it runs on your machine, from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app: up to ten images a second, through its next tests and stops.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/watch-running-test.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/watch-running-test.html"}],["meta",{"property":"og:title","content":"Watch a running test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Watch the page of a Playwright test while it runs on your machine, from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app: up to ten images a second, through its next tests and stops."}]]},"headers":[],"relativePath":"features/watch-running-test.md","filePath":"features/watch-running-test.md","lastUpdated":1794291722000}`),w={name:"features/watch-running-test.md"};function p(l,t,c,u,g,m){const a=o("Needs");return r(),n("div",null,[t[0]||(t[0]=e("h1",{id:"watch-a-running-test",tabindex:"-1"},[i("Watch a running test "),e("a",{class:"header-anchor",href:"#watch-a-running-test","aria-label":'Permalink to "Watch a running test"'},"​")],-1)),h(a,{reporter:"",fixtures:""}),t[1]||(t[1]=d('<p>A test that runs headless on your machine, or in a remote container, shows its page while it runs: up to ten images a second, through its next tests and its stops, and the worker Playwright starts in its place after a failure. Choose a worker in your editor, in Piwi Picker&#39;s Runs window or in the desktop app, and watch it work; <strong>Pause and watch</strong> stops it before its next call too. It needs <code>@piwitests/reporter</code> newer than 0.67.0 and the <a href="/guide/capture-fixtures.html">capture fixtures</a>. Nothing leaves your machine.</p><h2 id="where-to-watch" tabindex="-1">Where to watch <a class="header-anchor" href="#where-to-watch" aria-label="Permalink to &quot;Where to watch&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>Open it</th><th>At a stop</th></tr></thead><tbody><tr><td>VS Code</td><td><strong>Piwi: Watch a worker&#39;s test</strong>, or a click on the run&#39;s progress in the status bar: <strong>Piwi: worker 2</strong> beside the editor</td><td>A headless stop of the worker shows there, with <strong>Interact</strong> and the pick on a click, instead of the paused page</td></tr><tr><td>JetBrains IDEs</td><td><strong>Tools → Piwi → Watch a Worker&#39;s Test</strong>: the <strong>Worker 2</strong> tab of the Piwi tool window</td><td>The tab only watches: a headless stop opens the <strong>Paused Page</strong> beside it, for <strong>Interact</strong>, unless that tab holds another stop</td></tr><tr><td>Piwi Picker</td><td><strong>Watch</strong> on a worker&#39;s row of the <a href="./runs-window.html#watch-live">Runs window</a></td><td>The controls show above the view, and the stopped worker scrolls into view</td></tr><tr><td>Desktop app</td><td><strong>Watch</strong> on a running row of its own runs, which opens the <a href="./desktop-runs.html#watch-live">Local runs</a> tray on it</td><td>The tray scrolls the stopped worker into view</td></tr></tbody></table><p><strong>Pause and watch</strong> is <strong>Piwi: Pause and watch a worker&#39;s test</strong> in VS Code, <strong>Tools → Piwi → Pause and Watch a Worker&#39;s Test</strong> in a JetBrains IDE, and a button beside <strong>Watch</strong> in the Runs window and the desktop app. With several workers to choose from, the editor asks which.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Each view names the worker by its slot in the run (<code>Worker 2</code>) and says what it does: its running test, the call a Pause waits in, where it stopped, between tests, or starting. Across a <strong>Step</strong>, a <strong>Resume</strong> or between two tests, the last image stays until the next one comes, dimmed in VS Code, the Runs window and the desktop app. A page that does not change sends no new image.</p><p>Watching pauses while the view is out of sight (another tab in front of an editor&#39;s panel or tab, a minimized Runs window) and starts again as it shows. It ends when you turn it off or close the view, or as the run ends.</p><h2 id="what-is-sent-and-what-is-kept" tabindex="-1">What is sent, and what is kept <a class="header-anchor" href="#what-is-sent-and-what-is-kept" aria-label="Permalink to &quot;What is sent, and what is kept&quot;">​</a></h2><p>The worker takes images only while a view watches it, and sends them to the editor service or the desktop app&#39;s server on your machine, which passes each to the views watching that worker and keeps none. Before an image leaves the worker, password fields and the fields of one-time codes and card numbers are painted over. One view of the page serves every viewer at once: the editor&#39;s, Piwi Picker&#39;s and, for a run <a href="./share-live.html">shared live</a>, the team&#39;s.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>One worker per editor.</strong> The panel or tab watches one worker: watching another moves it there.</li><li><strong>The test&#39;s <code>page</code>.</strong> A popup or a second page the test opens is not shown.</li><li><strong>An older reporter</strong> shows a stopped test alone: the Runs window&#39;s row says to update it, and the editors offer no Watch for its workers.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./runs-window.html">Runs window</a>: watch, steer and pick from a window beside the test&#39;s browser.</li><li><a href="./editor-run-control.html">Pause and step from the editor</a>: the controls and the paused page, in the editor.</li><li><a href="./desktop-runs.html">Desktop app runs</a>: the runs the desktop app starts, and its tray.</li><li><a href="./live-view.html">Live view of a run</a>: a CI run&#39;s or a shared run&#39;s page, on the team instance.</li></ul>',13))])}const P=s(w,[["render",p]]);export{k as __pageData,P as default};
